$(document).ready(function(){if($(window).width()<1200){$(".contacts__section__inner .row").append($(".hidden_req"))}$(".phone__input").mask("+7(999) 999-9999");$("form").on("submit",function(e){e.preventDefault();$.ajax({type:"POST",url:"/form-submit.php",data:$(this).serialize(),dataType:"html",success:function(response){if(parseInt(response)===0||parseInt(response)===2){alert("Не все обязательные поля заполнены")}if(parseInt(response)===1){if($("#overflow").hasClass("active")){$(".popup_block").removeClass("active");$("#success_popup").addClass("active")}else{$("#success_popup").addClass("active");$("#overflow").addClass("active")}}}})});$(".show_req").on("click",function(){if($(this).hasClass("active")){$(".hidden_req").hide().show().slideToggle(150)}else{$(".hidden_req").show().hide().slideToggle(150)}$(this).toggleClass("active")});$(".burger_block").on("click",function(){if($(this).hasClass("active")){$(".burger__dropdown").hide().show().slideToggle(150)}else{$(".burger__dropdown").show().hide().slideToggle(150)}$(this).toggleClass("active");$("#overflow").toggleClass("active")});$(".c_popup").on("click",function(){let popup=$(this).attr("popup");$("#"+popup).addClass("active");$("#overflow").addClass("active")});$(".hide_popup").on("click",function(){$(".popup_block").removeClass("active");$("#overflow").removeClass("active")});$(document).click(function(e){const overflow=$("#overflow");if(overflow.is(e.target)){if($(".burger_block").hasClass("active")){$(".burger_block").removeClass("active");$(".burger__dropdown").hide().show().slideToggle(150)}$(".popup_block").removeClass("active");$("#overflow").removeClass("active")}});$(".block_href").on("click",function(){let href=$(this).attr("с_href");$(".burger_block").removeClass("active");$(".popup_block").removeClass("active");$("#overflow").removeClass("active");$(".burger__dropdown").hide().show().slideToggle(150);$("html, body").animate({scrollTop:$(href).offset().top},"slow")});const services=new Swiper(".services__slider",{spaceBetween:32,slidesPerView:1,breakpoints:{769:{slidesPerView:1.4},1400:{slidesPerView:2.9}},navigation:{nextEl:".services__slider .swiper-button-next",prevEl:".services__slider .swiper-button-prev"},scrollbar:{el:".services__slider .swiper-scrollbar",draggable:true}});const reviews=new Swiper(".reviews__slider",{spaceBetween:32,slidesPerView:1,pagination:{el:".reviews__slider .swiper-pagination",clickable:true},breakpoints:{769:{slidesPerView:2},1400:{slidesPerView:3}}})});